theorem fiberCubic_deriv_identity {x y z a b c : K}
    (h : F K (x, y, z) = (a, b, c)) :
    3 * c * (x * y + 1) ^ 2 - 4 * x * (x * y + 1) + b * x ^ 2 = 2 * x

theorem fiberCubic_on_curve [CharZero K] {a b c : K}
    (h12 : 12 * a = b ^ 2) (h34 : 3 * b * c = 4) (T : K) :
    c * T ^ 3 - 2 * T ^ 2 + b * T - 2 * a = c * (T - 2 / (3 * c)) ^ 3

theorem other_simpleRoot_at_infinity {a b t : K}
    (h : -2 * t ^ 2 + b * t - 2 * a = 0 ∧ -4 * t + b ≠ 0) :
    ∃ s : K, (-2 * s ^ 2 + b * s - 2 * a = 0 ∧ -4 * s + b ≠ 0) ∧ s ≠ t

theorem projectiveFiberPoint_resolvent {a b c : K}
    (p : {p : K × K × K // F K p = (a, b, c)}) :
    projectiveFiberPoint (projectiveResolvent p) = p

theorem projectiveResolvent_fiberPoint {a b c : K}
    (t : {t : Option K // projectiveSimpleRoot a b c t}) :
    projectiveResolvent (projectiveFiberPoint t) = t

theorem tau_cubic {A r t u : K}
    (h1 : chartG₁ A t u = 0) (h2 : chartG₂ r t u = 0) :
    sheetCubic A r t = 0

theorem two_fiber_points_extend_to_three {a b c : K} {p₁ p₂ : K × K × K}
    (h₁ : F K p₁ = (a, b, c)) (h₂ : F K p₂ = (a, b, c)) (hne : p₁ ≠ p₂) :
    ∃ p₃, F K p₃ = (a, b, c) ∧ p₃ ≠ p₁ ∧ p₃ ≠ p₂

theorem wallN_eq_zero_of_double_root {A r t : K}
    (hQ : sheetCubic A r t = 0) (hD : wallD r t = 0) :
    wallN A r t = 0

theorem wallW_eq_zero_of_onMissedCurve [CharZero K] {a b c : K}
    (h : OnMissedCurve a b c) :
    27 * a ^ 2 * c ^ 2 - 18 * a * b * c + 16 * a + b ^ 3 * c - b ^ 2 = 0

theorem fiber_ncard_le_one_of_wallW_eq_zero [NeZero (2 : K)] {a b c : K}
    (hW : wallW a b c = 0) :
    Set.ncard {p : K × K × K | F K p = (a, b, c)} ≤ 1

theorem wallW_ne_zero_of_simpleRoot_czero {a b t : K}
    (hP : -2 * t ^ 2 + b * t - 2 * a = 0) (hd : -4 * t + b ≠ 0) :
    wallW a b 0 ≠ 0

theorem wallW_ne_zero_of_two_fiber_points [NeZero (2 : K)] {a b c : K}
    {p₁ p₂ : K × K × K} (h₁ : F K p₁ = (a, b, c)) (h₂ : F K p₂ = (a, b, c))
    (hne : p₁ ≠ p₂) : wallW a b c ≠ 0

theorem card_forbidden_pairs :
    (Finset.univ.filter fun p : K × K =>
        p.2 ≠ p.1 ∧ 2 * p.1 + p.2 ≠ 0 ∧ p.1 + 2 * p.2 ≠ 0).card =
      if (3 : K) = 0 then Fintype.card K * (Fintype.card K - 1)
      else (Fintype.card K - 1) * (Fintype.card K - 2)
